package domain

// Account represents a financial account.
// ID is a unique identifier (e.g., UUID) generated by the repository.
// Name is the user‑provided name of the account.
// Balance and Budget are monetary values associated with the account.
type Account struct {
	ID      string  `json:"id"`
	Name    string  `json:"name"`
	Balance float64 `json:"balance"`
	Budget  float64 `json:"budget"`
}
